#!/usr/bin/env python3
"""Minimal expect-style driver over a TCP serial console for the Alpine VM.
Reads/writes a socket, matches patterns, with timeouts. Used to automate the
guest setup (login, bring up networking, install sshd, set root password, etc).
"""
import socket
import sys
import time

HOST = "127.0.0.1"
PORT = 4555


class Console:
    def __init__(self, host=HOST, port=PORT, logpath="/tmp/sertrace.log"):
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.connect((host, port))
        self.sock.setblocking(False)
        self.buf = b""
        self.log = open(logpath, "ab")
        self._logpath = logpath
        print(f"[drv] connected to {host}:{port} (log -> {logpath})", flush=True)

    def _drain(self, timeout):
        end = time.time() + timeout
        while time.time() < end:
            try:
                data = self.sock.recv(4096)
                if not data:
                    break
                self.buf += data
                self.log.write(data)
                self.log.flush()
            except BlockingIOError:
                time.sleep(0.05)
            except OSError:
                time.sleep(0.05)

    def expect(self, pattern, timeout=60, from_start=False):
        """Return (matched_bool, elapsed). pattern is bytes or str."""
        if isinstance(pattern, str):
            pattern = pattern.encode()
        start = time.time()
        # search whole accumulated buffer by default, but if from_start, search only data after now
        mark = len(self.buf) if from_start else 0
        while True:
            self._drain(0.2)
            if pattern in self.buf[mark:]:
                return True, time.time() - start
            if time.time() - start > timeout:
                return False, time.time() - start

    def send(self, data):
        if isinstance(data, str):
            data = data.encode()
        self.log.write(b">>> " + data + b"\n")
        self.log.flush()
        total = 0
        while total < len(data):
            try:
                n = self.sock.send(data[total:])
                if n == 0:
                    raise RuntimeError("socket send returned 0")
                total += n
            except BlockingIOError:
                time.sleep(0.02)
        return total

    def sendline(self, data=""):
        self.send(data + "\n")

    def snapshot(self):
        """Drain and return the accumulated buffer as text."""
        self._drain(0.5)
        try:
            return self.buf.decode("utf-8", "replace")
        except Exception:
            return repr(self.buf)

    def reset_buffer(self):
        self.buf = b"""""


if __name__ == "__main__":
    print("console driver module")

