import socket
import sys
import time

HOST = "127.0.0.1"
PORT = 4555


class Console:
    def __init__(self, host=HOST, port=PORT, logpath="/app/.stella/vmrun/sertrace.log"):
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.connect((host, port))
        self.sock.setblocking(False)
