        if isinstance(pattern, str):
            pattern = pattern.encode()
        start = time.time()
        # search whole accumulated buffer by default; if from_start, only data after now
        mark = len(self.buf) if from_start else 0
        while True:
            self._drain(0.2)
            if pattern in self.buf[mark:]:
                return True, time.time() - start
            if time.time() - start > timeout:
                return False, time.time() - start

    def send(self, data):
        if isinstance(data, str):
            data = data.encode()
        self.log.write(b">>> " + data + b"\n")
        self.log.flush()
        total = 0
        while total < len(data):
            try:
                n = self.sock.send(data[total:])
                if n == 0:
                    raise RuntimeError("socket send returned 0")
                total += n
            except BlockingIOError:
                time.sleep(0.02)
        return total

    def sendline(self, data=""):
        self.send(data + "\n")

    def snapshot(self):
        """Drain and return the accumulated buffer as text."""
        self._drain(0.5)
        try:
            return self.buf.decode("utf-8", "replace")
        except Exception:
            return repr(self.buf)

    def reset_buffer(self):
        self.buf = b""


