#!/usr/bin/expect -f
# End-to-end test: ssh into the guest on port 2222 with password auth,
# run a command, and prove we got a shell inside the VM.
set timeout 40
set password "password123"

# Accept new host key automatically
spawn ssh -p 2222 \
    -o StrictHostKeyChecking=no \
    -o UserKnownHostsFile=/dev/null \
    -o PreferredAuthentications=password \
    -o PubkeyAuthentication=no \
    root@localhost

expect {
    -re "(?i)password:" {
        send "$password\r"
    }
    timeout { puts "\n[FAIL] timed out waiting for password prompt"; exit 2 }
    eof { puts "\n[FAIL] connection closed before password prompt"; exit 3 }
}

# Wait for the remote shell prompt
expect {
    -re "(localhost|#|\\$) *$" {
        puts "\n[OK] got shell prompt"
    }
    -re "(?i)permission denied" { puts "\n[FAIL] permission denied (wrong password / sshd config)"; exit 4 }
    timeout { puts "\n[FAIL] timed out waiting for shell prompt"; exit 5 }
}

# Run a command to prove we're inside the VM, then exit cleanly
send "echo SHELLCHECK_\$(uname -sr); cat /etc/alpine-release\r"
expect {
    -re "SHELLCHECK_Linux.*Alpine" {
        puts "\n[OK] command output confirms Alpine guest shell"
    }
    -re "SHELLCHECK_" {
        puts "\n[OK] got shell command output"
    }
    timeout { puts "\n[FAIL] timed out waiting for command output"; exit 6 }
}
send "exit\r"
expect eof
puts "\n[SUCCESS] ssh e2e test passed"
exit 0

